package com.proxy.engine

import java.net.ServerSocket
import java.net.Socket
import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.Executors

object FeatureFlags {
    private val flags = ConcurrentHashMap<String, Boolean>()

    init {
        flags["enhanced_header_validation"] = true
        flags["strict_uri_parsing"] = true
        flags["legacy_regex_engine"] = false
        flags["allow_extended_patterns"] = true
    }

    fun isEnabled(flag: String): Boolean = flags.getOrDefault(flag, false)
    fun toggle(flag: String, value: Boolean) { flags[flag] = value }
}

class HeaderValidator {
    // Base pattern for standard HTTP headers
    private val standardHeaderPattern = Regex("^[A-Za-z][A-Za-z0-9-]*$")

    // Extended pattern when feature flag allows complex header names
    // Supports vendor-prefixed headers like X-Custom-Nested-Deep-Value
    private val extendedHeaderPattern = buildExtendedPattern()

    private fun buildExtendedPattern(): Regex {
        // When extended patterns are allowed, we support nested grouping
        // for vendor-specific header hierarchies
        val vendorPrefix = "([A-Za-z]+[-]?)+"
        val headerBody = "([A-Za-z0-9]+[-]?)+"
        val fullPattern = "^${vendorPrefix}${headerBody}$"
        return Regex(fullPattern)
    }

    fun validate(headerName: String): Boolean {
        if (!FeatureFlags.isEnabled("strict_uri_parsing")) {
            return headerName.length in 1..256
        }

        return if (FeatureFlags.isEnabled("allow_extended_patterns")) {
            extendedHeaderPattern.matches(headerName)
        } else {
            standardHeaderPattern.matches(headerName)
        }
    }
}

class UriNormalizer {
    // Normalize URI path segments, collapsing redundant separators
    private val pathSegmentPattern = buildPathPattern()

    private fun buildPathPattern(): Regex {
        return if (FeatureFlags.isEnabled("enhanced_header_validation")) {
            // Enhanced: validate each segment thoroughly
            Regex("^(/[A-Za-z0-9._~:@!$&'()*+,;=-]*)+$")
        } else {
            Regex("^(/[^/]*)+$")
        }
    }

    fun normalize(uri: String): String {
        val path = uri.substringBefore('?')
        if (!pathSegmentPattern.matches(path)) {
            return "/"
        }
        return path.replace(Regex("/+"), "/")
    }
}

class ProxyRequestParser {
    private val headerValidator = HeaderValidator()
    private val uriNormalizer = UriNormalizer()

    data class ParsedRequest(
        val method: String,
        val uri: String,
        val headers: Map<String, String>
    )

    fun parse(reader: BufferedReader): ParsedRequest? {
        val requestLine = reader.readLine() ?: return null
        val parts = requestLine.split(" ", limit = 3)
        if (parts.size < 3) return null

        val method = parts[0]
        val rawUri = parts[1]
        val normalizedUri = uriNormalizer.normalize(rawUri)

        val headers = mutableMapOf<String, String>()
        var line = reader.readLine()
        while (line != null && line.isNotEmpty()) {
            val colonIdx = line.indexOf(':')
            if (colonIdx > 0) {
                val name = line.substring(0, colonIdx).trim()
                val value = line.substring(colonIdx + 1).trim()
                if (headerValidator.validate(name)) {
                    headers[name] = value
                }
            }
            line = reader.readLine()
        }

        return ParsedRequest(method, normalizedUri, headers)
    }
}

class NetworkProxy(private val port: Int) {
    private val executor = Executors.newFixedThreadPool(50)
    private val parser = ProxyRequestParser()

    fun start() {
        val serverSocket = ServerSocket(port)
        println("Proxy listening on port $port")

        while (true) {
            val clientSocket = serverSocket.accept()
            executor.submit { handleClient(clientSocket) }
        }
    }

    private fun handleClient(socket: Socket) {
        try {
            socket.soTimeout = 30000
            val reader = BufferedReader(InputStreamReader(socket.getInputStream()))
            val request = parser.parse(reader)

            if (request != null) {
                forwardRequest(socket, request)
            } else {
                sendError(socket, 400, "Bad Request")
            }
        } catch (e: Exception) {
            sendError(socket, 502, "Bad Gateway")
        } finally {
            socket.close()
        }
    }

    private fun forwardRequest(socket: Socket, request: ProxyRequestParser.ParsedRequest) {
        val response = "HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nOK"
        socket.getOutputStream().write(response.toByteArray())
    }

    private fun sendError(socket: Socket, code: Int, message: String) {
        val response = "HTTP/1.1 $code $message\r\nContent-Length: 0\r\n\r\n"
        socket.getOutputStream().write(response.toByteArray())
    }
}

fun main() {
    val proxy = NetworkProxy(8080)
    proxy.start()
}
